import openpyxl, os, sys, json
from openpyxl.utils import get_column_letter
out='/root/output/result.xlsx'
wb=openpyxl.load_workbook(out, data_only=False)
ws=wb['Task']
errors=[]
expected_sheets=['Task','Data']
if wb.sheetnames != expected_sheets:
    errors.append(f'sheets {wb.sheetnames} != {expected_sheets}')

def formula(cell):
    v=cell.value
    return isinstance(v,str) and v.startswith('=')

# Verify lookup ranges
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            v=ws.cell(r,c).value
            col=get_column_letter(c)
            exp=f'=INDEX(Data!$D$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({col}$10, Data!$D$4:$L$4, 0))'
            if v != exp:
                errors.append(f'{col}{r} expected {exp!r}, got {v!r}')

# Verify reliability gap formulas
for r in range(35,41):
    off=r-35
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=({col}{12+off}-{col}{19+off})/{col}{26+off}*100'
        v=ws.cell(r,c).value
        if v != exp:
            errors.append(f'{col}{r} expected {exp!r}, got {v!r}')

# Verify stats formulas
stat_templates={
42:'=MIN({col}35:{col}40)',
43:'=MAX({col}35:{col}40)',
44:'=MEDIAN({col}35:{col}40)',
45:'=AVERAGE({col}35:{col}40)',
46:'=PERCENTILE.INC({col}35:{col}40, 0.25)',
47:'=PERCENTILE.INC({col}35:{col}40, 0.75)',
}
for r, tmpl in stat_templates.items():
    for c in range(8,13):
        col=get_column_letter(c)
        exp=tmpl.format(col=col)
        v=ws.cell(r,c).value
        if v != exp:
            errors.append(f'{col}{r} expected {exp!r}, got {v!r}')

# Verify weighted mean
for c in range(8,13):
    col=get_column_letter(c)
    exp=f'=SUMPRODUCT({col}35:{col}40, {col}26:{col}31) / SUM({col}26:{col}31)'
    v=ws.cell(50,c).value
    if v != exp:
        errors.append(f'{col}50 expected {exp!r}, got {v!r}')

print('Workbook:', out)
print('Size:', os.path.getsize(out))
print('Sheets:', wb.sheetnames)
print('No extra sheets:', wb.sheetnames == expected_sheets)
print('\nSample formulas:')
for addr in ['H12','I12','L17','H19','L24','H26','L31','H35','L40','H42','H43','H44','H45','H46','H47','H50','L50']:
    print(addr, ws[addr].value)
print('\nFormula presence counts:')
for label, ranges in [
    ('lookup blocks', [(12,17),(19,24),(26,31)]),
    ('gap block', [(35,40)]),
    ('summary block', [(42,47)]),
    ('weighted row', [(50,50)]),
]:
    total=0; ok=0
    for start,end in ranges:
        for r in range(start,end+1):
            for c in range(8,13):
                total += 1
                ok += formula(ws.cell(r,c))
    print(label, ok, '/', total)

if errors:
    print('\nERRORS:')
    for e in errors[:50]: print(e)
    print('total errors', len(errors))
    sys.exit(1)
print('\nValidation passed')
